// Isolated browser-only QA of EXO's living factory tech-pack workflow.
// Uses a separate Playwright context and testSession; never touches the installed app.
import assert from 'node:assert/strict'
import path from 'node:path'
import {readFile} from 'node:fs/promises'
import {chromium} from 'playwright-core'
const origin=process.env.EXO_TECHPACK_QA_URL||'http://127.0.0.1:6227'
const output=process.env.EXO_TECHPACK_QA_SCREENSHOT||path.resolve('screenshots/qa-digital-techpack-20261018.png')
const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--enable-webgl','--ignore-gpu-blocklist','--use-angle=metal']})
const report={origin,checks:[],errors:[],screenshot:output}
const check=(name,value)=>{assert(value,name);report.checks.push(name)}
try{
  const context=await browser.newContext({viewport:{width:1580,height:980},acceptDownloads:true})
  const page=await context.newPage()
  page.on('pageerror',error=>report.errors.push(error.message))
  const dialogs=[]
  page.on('dialog',dialog=>{dialogs.push(dialog.message());void dialog.accept()})
  await page.goto(origin+'/?desktop=1&techpack=1&testSession=tee',{waitUntil:'domcontentloaded',timeout:45000})
  const studio=page.getByRole('dialog',{name:'Digital tech pack'})
  await studio.waitFor({timeout:45000})
  check('Tech Pack Studio opens directly',await studio.isVisible())
  const paper=studio.locator('iframe[title="Full traditional tech pack document"]')
  await paper.waitFor()
  check('Traditional factory Tech Pack is embedded inside EXO application',await paper.isVisible())
  const paperContents=await paper.contentFrame().locator('body').innerText()
  check('Embedded PDF-style layout is complete and derived from garment specs',/Bill of materials|Points of measure/i.test(paperContents)&&/construction|reference photos/i.test(paperContents))
  await studio.getByRole('tab',{name:'Digital Board'}).click()
  const style=studio.getByLabel('Style number')
  await style.fill('EXO-TECH-QA-001')
  check('Style number accepts editing',await style.inputValue()==='EXO-TECH-QA-001')
  await studio.getByRole('button',{name:'Measurements'}).click()
  const firstTolerance=studio.locator('.dtp-cell-input[aria-label$="tolerance cm"]').first()
  await firstTolerance.waitFor()
  await firstTolerance.fill('0.8')
  check('Editable POM tolerance accepts centimeters',await firstTolerance.inputValue()==='0.8')
  const firstMeasured=studio.locator('.dtp-cell-input[aria-label$=" cm"]:not([aria-label$="tolerance cm"])').first()
  const measurementLabel=await firstMeasured.getAttribute('aria-label')
  const sizeValue=measurementLabel.split(' ').at(-2)
  const measuredBefore=Number(await firstMeasured.inputValue())
  const measuredTarget=Number((measuredBefore+5).toFixed(2))
  await firstMeasured.fill(String(measuredTarget))
  check('Editable graded measurement accepts a spec override',Number(await firstMeasured.inputValue())===measuredTarget)
  await studio.getByRole('button',{name:'Materials & BOM'}).click()
  const supplier=studio.locator('.dtp-cell-input[aria-label$="supplier"]').first()
  await supplier.waitFor()
  await supplier.fill('QA supplier mill')
  check('BOM supplier is editable',await supplier.inputValue()==='QA supplier mill')
  await studio.getByRole('button',{name:'Save version'}).first().click()
  await studio.getByRole('button',{name:'Versions'}).click()
  await studio.getByText('Draft 1').first().waitFor()
  check('Save version creates immutable draft snapshot',true)
  await studio.getByRole('button',{name:'Overview'}).click()
  await style.fill('EXO-TECH-QA-002')
  await studio.getByRole('button',{name:'Versions'}).click()
  await studio.getByRole('button',{name:'Compare with draft'}).first().click()
  check('Version diff shows source and new style',await studio.getByText('EXO-TECH-QA-001').count()>0&&await studio.getByText('EXO-TECH-QA-002').count()>0)
  await studio.getByRole('button',{name:'Comments'}).click()
  await studio.getByLabel('New comment').fill('QA: confirm collar stitch spec')
  await studio.getByRole('button',{name:'Comment',exact:true}).click()
  check('Section comment persists in working draft',await studio.getByText('QA: confirm collar stitch spec').isVisible())
  await studio.getByRole('button',{name:'Sampling'}).click()
  await studio.getByLabel('Sample round').fill('First fit prototype')
  await studio.getByRole('button',{name:'Add round'}).click()
  check('Sample round added',await studio.getByText('First fit prototype').isVisible())
  await studio.getByRole('button',{name:'Overview'}).click()
  await studio.getByLabel('Factory').fill('Test manufacturer A')
  await studio.getByRole('button',{name:'Factory releases'}).click()
  await studio.getByRole('button',{name:'Create local release'}).click()
  check('Manufacturer-specific version release stored',await studio.getByText('R01 · Test manufacturer A').count()>0)
  const pending=page.waitForEvent('download',{timeout:15000})
  await studio.getByRole('button',{name:'Download JSON'}).click()
  const download=await pending
  check('Digital JSON export downloads',download.suggestedFilename().endsWith('.json'))
  const exported=JSON.parse(await readFile(await download.path(),'utf8'))
  check('Download contains editable draft and original garment source',Boolean(exported.studio?.draft?.pom && exported.studio?.source?.sizeMeasurements))
  const firstId=exported.studio.draft.pom[sizeValue]?.[0]?.id
  const exportMeasurement=exported.studio.draft.pom[sizeValue]?.find(row=>row.id===firstId)
  const sourceMeasurement=exported.studio.source.sizeMeasurements?.[sizeValue]?.find(row=>row.id===firstId)
  check('Draft POM edited without mutating source POM',Number(exportMeasurement?.cm)===measuredTarget&&Number(sourceMeasurement?.cm)===measuredBefore)
  check('BOM supplier persists in export',exported.studio.draft.bom.some(m=>m.supplier==='QA supplier mill'))
  await studio.getByRole('tab',{name:'Reference Board'}).click()
  const png=await readFile(path.resolve('public/hardware-thumbnails/black-matte-button.png'))
  await studio.locator('input[type="file"][accept="image/png,image/jpeg,image/webp"]').setInputFiles({name:'test-reference.png',mimeType:'image/png',buffer:png})
  await page.waitForTimeout(350)
  assert(!dialogs.some(x=>/Could not add|Only PNG/i.test(x)),`Reference upload rejected: ${dialogs.join(' | ')}`)
  await studio.getByLabel('Edit reference caption').waitFor()
  await studio.getByLabel('Edit reference caption').fill('QA shoulder reference')
  check('Reference Board accepts an image with an editable caption',await studio.getByLabel('Edit reference caption').inputValue()==='QA shoulder reference')
  await studio.getByLabel('New annotation text').fill('Check shoulder construction')
  await studio.locator('.dtp-annotatable').click({position:{x:25,y:25}})
  check('Reference board accepts an image-anchored callout',await studio.locator('.dtp-pin').count()===1)
  await studio.getByRole('button',{name:'Set technical flat'}).click()
  check('Reference image can become the printable technical flat',await studio.getByRole('button',{name:'Set technical flat'}).getAttribute('aria-pressed')==='true')
  await studio.getByRole('tab',{name:'Traditional Tech Pack'}).click()
  check('Full traditional document updates with selected technical flat',await paper.contentFrame().getByAltText('QA shoulder reference').count()>0)
  const htmlDownloadEvent=page.waitForEvent('download',{timeout:15000})
  await studio.getByRole('button',{name:'Export HTML'}).click()
  const htmlDownload=await htmlDownloadEvent
  check('Portable digital Tech Pack HTML downloads',htmlDownload.suggestedFilename().endsWith('.html'))
  const exportedHTML=await readFile(await htmlDownload.path(),'utf8')
  check('Portable HTML includes both the factory specification and image callouts',exportedHTML.includes('Factory PDF layout')&&exportedHTML.includes('Check shoulder construction'))
  await page.waitForTimeout(1100)
  await page.reload({waitUntil:'domcontentloaded'})
  await studio.waitFor({timeout:45000})
  await studio.getByRole('tab',{name:'Digital Board'}).click()
  await studio.getByRole('button',{name:'Overview'}).click()
  check('Tech pack draft survives isolated project autosave and reload',await studio.getByLabel('Style number').inputValue()==='EXO-TECH-QA-002')
  await studio.getByRole('button',{name:'Factory releases'}).click()
  check('Immutable release survives reload',await studio.getByText('R01 · Test manufacturer A').count()>0)
  await page.screenshot({path:output,fullPage:true})
  check('No uncaught page errors',report.errors.length===0)
  report.pass=true
}catch(error){report.pass=false;report.failure=error.stack||String(error);process.exitCode=1}
finally{console.log(JSON.stringify(report,null,2));await browser.close()}
